#[derive(Debug, PartialEq)]
pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }

    const PREFIX: &str = "{\"v\":2,\"hello\":\"";
    if let Some(value) = bytes.strip_prefix(PREFIX).and_then(|value| value.strip_suffix("\"}")) {
        return unescape_json_string(value).map(Msg::Hello);
    }

    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!("{{\"v\":2,\"hello\":\"{}\"}}", escape_json_string(value)),
    }
}

fn escape_json_string(value: &str) -> String {
    let mut escaped = String::with_capacity(value.len());
    for character in value.chars() {
        match character {
            '"' => escaped.push_str("\\\""),
            '\\' => escaped.push_str("\\\\"),
            '\n' => escaped.push_str("\\n"),
            '\r' => escaped.push_str("\\r"),
            '\t' => escaped.push_str("\\t"),
            character if character < '\u{20}' => {
                escaped.push_str(&format!("\\u{:04x}", character as u32));
            }
            character => escaped.push(character),
        }
    }
    escaped
}

fn unescape_json_string(value: &str) -> Result<String, String> {
    let mut unescaped = String::with_capacity(value.len());
    let mut characters = value.chars();
    while let Some(character) = characters.next() {
        if character != '\\' {
            unescaped.push(character);
            continue;
        }

        match characters.next() {
            Some('"') => unescaped.push('"'),
            Some('\\') => unescaped.push('\\'),
            Some('/') => unescaped.push('/'),
            Some('b') => unescaped.push('\u{0008}'),
            Some('f') => unescaped.push('\u{000c}'),
            Some('n') => unescaped.push('\n'),
            Some('r') => unescaped.push('\r'),
            Some('t') => unescaped.push('\t'),
            Some('u') => {
                let digits: String = characters.by_ref().take(4).collect();
                if digits.len() != 4 || !digits.chars().all(|digit| digit.is_ascii_hexdigit()) {
                    return Err("unknown".into());
                }
                let code_point = u32::from_str_radix(&digits, 16).map_err(|_| "unknown".to_string())?;
                let character = char::from_u32(code_point).ok_or_else(|| "unknown".to_string())?;
                unescaped.push(character);
            }
            _ => return Err("unknown".into()),
        }
    }
    Ok(unescaped)
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn ping_encode_roundtrip() {
        let encoded = encode(&Msg::Ping);
        assert!(matches!(decode(&encoded), Ok(Msg::Ping)));
    }

    #[test]
    fn hello_uses_v2_envelope_and_roundtrips() {
        let encoded = encode(&Msg::Hello("Ada".into()));
        assert_eq!(encoded, r#"{"v":2,"hello":"Ada"}"#);
        assert!(matches!(decode(&encoded), Ok(Msg::Hello(value)) if value == "Ada"));
    }

    #[test]
    fn hello_escapes_json_string_content() {
        let message = Msg::Hello("say \"hi\"\\now".into());
        assert_eq!(decode(&encode(&message)), Ok(message));
    }

    #[test]
    fn unknown_input_returns_error() {
        assert_eq!(decode("unknown"), Err("unknown".into()));
    }
}
